PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX chop: <https://biomedit.ch/rdf/sphn-resource/chop/>
PREFIX snomed: <http://snomed.info/id/>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
PREFIX geno: <http://purl.obolibrary.org/obo/GENO_>
PREFIX bif: <bif:>
SELECT (AVG(?days) AS ?avg_length_of_stay_days) (COUNT(DISTINCT ?case) AS ?stays) WHERE {
  {
    SELECT DISTINCT ?g ?case ?admission ?discharge WHERE {
      GRAPH ?g {
        ?code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        ?dx sphn:hasCode ?code ; a sphn:BilledDiagnosis ; sphn:hasAdministrativeCase ?case .
        ?case sphn:hasAdmissionDateTime ?admission ; sphn:hasDischargeDateTime ?discharge .
      }
    }
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
}

