PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
PREFIX geno: <http://purl.obolibrary.org/obo/GENO_>
PREFIX bif: <bif:>
SELECT (AVG(?hours) AS ?avg_hours) (COUNT(*) AS ?administrations) WHERE {
  {
    SELECT DISTINCT ?a ?start ?end WHERE {
      GRAPH ?g { ?a a sphn:DrugAdministrationEvent ; sphn:hasStartDateTime ?start ; sphn:hasEndDateTime ?end . }
      FILTER (?end >= ?start)
    }
  }
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
}

