PREFIX snomed: <http://snomed.info/id/>
PREFIX ucum: <https://biomedit.ch/rdf/sphn-resource/ucum/>
PREFIX geno: <http://purl.obolibrary.org/obo/GENO_>
PREFIX bif: <bif:>
SELECT (AVG(?days) AS ?avg_days_to_first_radiotherapy) (COUNT(*) AS ?patients) WHERE {
  {
    SELECT ?g (MIN(?incidence) AS ?diagnosed) (MIN(?start) AS ?first_rt) WHERE {
      GRAPH ?g {
        ?dx a sphn:OncologyDiagnosis ; sphn:hasIncidenceDateTime ?incidence .
        ?rt a sphn:RadiotherapyProcedure ; sphn:hasStartDateTime ?start .
      }
      FILTER (?start > ?incidence)
    } GROUP BY ?g
  }
  BIND (bif:datediff("day", ?diagnosed, ?first_rt) AS ?days)
}

